import{createHash}from"node:crypto";export function buildGovernanceEvidenceBundleManifest({entries,snapshotHash,policyHash}){if(!entries.length||![snapshotHash,policyHash].every(x=>/^[a-f0-9]{64}$/.test(x||"")))throw Error("manifest invalid");entries=[...entries].sort((a,b)=>a.entryHash.localeCompare(b.entryHash));if(new Set(entries.map(x=>x.entryHash)).size!==entries.length)throw Error("duplicate");let b={kind:"governance-evidence-bundle-manifest/v1",entries:Object.freeze(entries),snapshotHash,policyHash};return Object.freeze({...b,manifestHash:createHash("sha256").update(JSON.stringify(b)).digest("hex")})}
